<?php
session_set_cookie_params(['lifetime'=>0,'path'=>'/','domain'=>'','secure'=>false,'httponly'=>true,'samesite'=>'Lax']);
session_start();
require_once 'db.php';
if (empty($_SESSION['user_id']) || !in_array($_SESSION['role'] ?? '', ['teacher','staff'], true)) { header('Location: faculty_login.php'); exit; }
$user_id=(int)$_SESSION['user_id']; $role=$_SESSION['role']; $back=$role==='teacher'?'faculty_dashboard.php':'staff_dashboard.php';
if(empty($_SESSION['csrf_token'])) $_SESSION['csrf_token']=bin2hex(random_bytes(32)); $csrf=$_SESSION['csrf_token'];
$error=''; $success='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!isset($_POST['csrf_token'])||!hash_equals($csrf,$_POST['csrf_token'])) $error='Your session expired. Please try again.';
 else{
  $current=$_POST['current_password']??''; $new=$_POST['new_password']??''; $confirm=$_POST['confirm_password']??'';
  $q=$mysqli->prepare('SELECT password_hash FROM users WHERE id=? LIMIT 1'); $q->bind_param('i',$user_id); $q->execute(); $u=$q->get_result()->fetch_assoc(); $q->close();
  if(!$u||!password_verify($current,$u['password_hash'])) $error='Current password is incorrect.';
  elseif(strlen($new)<8) $error='New password must be at least 8 characters.';
  elseif($new!==$confirm) $error='New password and confirmation do not match.';
  elseif(password_verify($new,$u['password_hash'])) $error='New password must be different from your current password.';
  else{$hash=password_hash($new,PASSWORD_DEFAULT);$up=$mysqli->prepare('UPDATE users SET password_hash=? WHERE id=?');$up->bind_param('si',$hash,$user_id);$up->execute();$up->close();$success='Password updated successfully.';}
 }
}
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Change Password — PBI</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css"><style>:root{--dark:#0A192F;--mid:#172A45;--inner:#0F1F3D;--teal:#0D9488;--light:#E0E6F0;--muted:#A0B3C6;--border:rgba(255,255,255,.08)}*{box-sizing:border-box}body{margin:0;background:var(--dark);color:var(--light);font-family:Arial,sans-serif;min-height:100vh;display:flex;align-items:center;justify-content:center;padding:24px}.card{width:100%;max-width:500px;background:var(--mid);border:1px solid var(--border);border-radius:16px;padding:28px;box-shadow:0 18px 50px rgba(0,0,0,.3)}.head{display:flex;align-items:center;gap:14px;margin-bottom:22px}.icon{width:48px;height:48px;border-radius:12px;background:rgba(13,148,136,.14);color:#14B8A6;display:flex;align-items:center;justify-content:center;font-size:20px}.head h1{font-size:22px;margin:0}.head p{font-size:12px;color:var(--muted);margin:4px 0 0}.field{margin-bottom:15px}.field label{display:block;font-size:12px;font-weight:700;margin-bottom:7px}.field input{width:100%;padding:12px 13px;border:1px solid var(--border);background:var(--inner);color:var(--light);border-radius:9px;outline:none}.field input:focus{border-color:var(--teal)}.msg{padding:11px 13px;border-radius:9px;font-size:12px;margin-bottom:16px}.err{background:rgba(240,84,84,.1);color:#fca5a5;border:1px solid rgba(240,84,84,.2)}.ok{background:rgba(34,197,94,.1);color:#86efac;border:1px solid rgba(34,197,94,.2)}.actions{display:flex;justify-content:flex-end;gap:10px;margin-top:20px}.btn{padding:11px 16px;border-radius:9px;font-weight:700;text-decoration:none;border:0;cursor:pointer}.back{background:transparent;color:var(--muted);border:1px solid var(--border)}.save{background:var(--teal);color:#fff}</style></head><body><div class="card"><div class="head"><div class="icon"><i class="fa-solid fa-lock"></i></div><div><h1>Change Password</h1><p>Update your <?= $role==='teacher'?'faculty':'staff' ?> account password.</p></div></div><?php if($error): ?><div class="msg err"><i class="fa-solid fa-circle-exclamation"></i> <?= htmlspecialchars($error) ?></div><?php endif;?><?php if($success): ?><div class="msg ok"><i class="fa-solid fa-circle-check"></i> <?= htmlspecialchars($success) ?></div><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrf) ?>"><div class="field"><label>Current Password</label><input type="password" name="current_password" required autocomplete="current-password"></div><div class="field"><label>New Password</label><input type="password" name="new_password" minlength="8" required autocomplete="new-password"></div><div class="field"><label>Confirm New Password</label><input type="password" name="confirm_password" minlength="8" required autocomplete="new-password"></div><div class="actions"><a class="btn back" href="<?= htmlspecialchars($back) ?>?page=profile">Cancel</a><button class="btn save" type="submit"><i class="fa-solid fa-key"></i> Update Password</button></div></form></div></body></html>
